import subprocess, os, re, sys
ROOT="/Users/michelkerkmeester/worktrees/public/315-frontend-reference-restructure"
files=subprocess.run(["git","-C",ROOT,"diff","--name-only","--",".skilled/skills/sk-design/sk-design-diagram"],capture_output=True,text=True).stdout.split()

def blocks(text):
    out=[]; cur=None; fence=None
    for line in text.splitlines():
        m=re.match(r"^\s*(```+|~~~+)",line)
        if cur is None:
            if m:
                fence=m.group(1)[0]*3; cur=[line.strip()]
        else:
            cur.append(line)
            if line.strip().startswith(fence) and len(line.strip())>=3 and set(line.strip())<=set(fence[0]):
                out.append("\n".join(cur)); cur=None
    return out

def fm(text):
    if text.startswith("---\n"):
        end=text.find("\n---",4)
        if end!=-1: return text[:end+4]
    return ""

for f in files:
    head=subprocess.run(["git","-C",ROOT,"show","HEAD:"+f],capture_output=True,text=True).stdout
    now=open(os.path.join(ROOT,f)).read()
    hb=blocks(head); nb=blocks(now)
    if len(hb)!=len(nb):
        print("BLOCKCOUNT",f,len(hb),len(nb))
    hs=set(b.strip() for b in hb); ns=set(b.strip() for b in nb)
    missing=hs-ns
    if missing:
        print("BLOCK-CHANGED",f,len(missing))
        for m in missing:
            print("   ---HEAD---")
            print("\n".join("   "+l for l in m.splitlines()[:8]))
    if fm(head)!=fm(now):
        print("FM-CHANGED",f)

