import subprocess, os, re
ROOT="/Users/michelkerkmeester/worktrees/public/315-frontend-reference-restructure"
files=subprocess.run(["git","-C",ROOT,"diff","--name-only","--",".skilled/skills/sk-design/sk-design-diagram"],capture_output=True,text=True).stdout.split()

def intro(text):
    lines=text.splitlines()
    # skip frontmatter
    i=0
    if lines and lines[0].strip()=="---":
        for j in range(1,len(lines)):
            if lines[j].strip()=="---":
                i=j+1; break
    # find H1
    for k in range(i,len(lines)):
        if lines[k].startswith("# "):
            i=k+1; break
    # collect until next heading or hr, ignoring blanks
    buf=[]
    for k in range(i,len(lines)):
        s=lines[k].strip()
        if s.startswith("#") or s=="---": break
        if s: buf.append(s)
    return " ".join(buf)

for f in files:
    head=subprocess.run(["git","-C",ROOT,"show","HEAD:"+f],capture_output=True,text=True).stdout
    now=open(os.path.join(ROOT,f)).read()
    a=intro(head); b=intro(now)
    if a!=b:
        print("=== "+f)
        print("  HEAD: "+a[:400])
        print("  NOW : "+b[:400])

